use Civi\Lughauth\Features\Access\Role\Domain\ValueObject\RoleVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class RoleListController
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly RoleListUsecase $listUsecase,
  ) {
  }
  #[OA\Get(path: "/api/access/roles", tags: ["Role"], description:"Create",
    responses: [
      new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/RoleApiListDTO")),
      new OA\Response(response: 422, description: "Constraint error"),
    ])
  ]
  public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("List Role");
    $span = $this->startSpan("List Role");
    try {
      $params = $request->getQueryParams();
      $filter = new RoleFilter(
        uids: isset( $params['uid'] ) ? [$params['uid']] : ( isset($params['uids']) ? explode(',', $params['uids']) : null),
        search: $params['search'] ?? null,
        name: $params['name'] ?? null,
        relyingParty: isset($params['relying-party'])? new RelyingPartyRef($params['relying-party']): null,
        relyingParties: isset($params['relying-parties'])? explode(",", $params['relying-parties']): null,
      );
      $cursor = new RoleCursor(
        limit: (int)($params['limit'] ?? 100),
        sinceUid: $params['since-uid']??null,
        sinceName: $params['since-name']??null,
        order: isset($params['order'])?$this->extractOrder( explode(',', $params['order']) ):null,
      );
      $result = $this->listUsecase->list($filter, $cursor);
      $value = ['items' => array_map(fn(RoleAttributes $item):RoleApiDTO => $this->mapRole($request, $item), $result->values())];
      $nextLink = count($result->values()) < $cursor->limit() ? null : $this->nextLink($result->cursor(), $params);
      if (null !== $nextLink) {
        $value['next'] = "?{$nextLink}";
      }
      $encoded = json_encode($value);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response->withStatus(200)
        ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function extractOrder(array $order): array
  {
    $this->logDebug("Extract order for Role");
    $span = $this->startSpan("Extract order for Role");
    try {
      $mapped = [];
      foreach($order as $ord) {
        if ($ord === 'name-asc' ) {
          $mapped[] = 'nameAsc';
        }
        if ($ord === 'name-desc' ) {
          $mapped[] = 'nameDesc';
        }
      }
      return $mapped;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function nextLink(?RoleCursor $value, array $params): ?string
  {
    $this->logDebug("Check generic allow for Role");
    $span = $this->startSpan("Generic allow for Role");
    try {
      if( !$value ) {
        return null;
      }
    $link = array_merge($params, [
                'since-uid' => $value->sinceUid(),
                'since-name' => $value->sinceName(),\r\n                'since-name' => $value->sinceName(),\r\n            ]);    return http_build_query(array_filter($link, fn (mixed $item): bool => null !== $item));
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  private function mapRole(ServerRequestInterface $request, RoleAttributes $value): RoleApiDTO
  {
    $this->logDebug("Map entity to output dto for Role");
    $span = $this->startSpan("Map entity to output dto for Role");
    try {
      $relyingParty = $value->getRelyingParty();
      $dto = new RoleApiDTO();
      $dto->uid = $value->getUid();
      $dto->name = $value->getName();
      $dto->relyingParty = $relyingParty ? ['$ref' => $relyingParty->uid()] : null;
      $dto->version = $value->getVersion();
      return $dto;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
